<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/functions.php';require_role(['admin']);$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['product_id']??0);$qty=(int)($_POST['quantity']??0);$reason=trim($_POST['reason']??'Manual adjustment');$st=$pdo->prepare('SELECT stock FROM products WHERE id=?');$st->execute([$id]);$old=$st->fetchColumn();if($old!==false && (int)$old+$qty>=0 && $qty!==0){$pdo->beginTransaction();try{$up=$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=?');$up->execute([$qty,$id]);$log=$pdo->prepare("INSERT INTO inventory_logs(product_id,change_qty,reason,reference_type) VALUES(?,?,?,'manual')");$log->execute([$id,$qty,$reason]);$pdo->commit();$message='Inventory updated.';}catch(Throwable $e){$pdo->rollBack();$message='Unable to update inventory.';}}else $message='Choose a product and enter a non-zero adjustment that does not make stock negative.';}
$products=$pdo->query('SELECT p.id,p.name,p.stock,p.price,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.stock ASC,p.name')->fetchAll();$logs=$pdo->query('SELECT l.*,p.name product_name FROM inventory_logs l LEFT JOIN products p ON p.id=l.product_id ORDER BY l.created_at DESC LIMIT 100')->fetchAll();$pageTitle='Inventory';include __DIR__.'/../includes/header.php';?>
<div class="admin-shell"><h1>INVENTORY MANAGEMENT</h1><nav class="admin-nav"><a href="index.php">Dashboard</a><a href="products.php">Products</a><a href="categories.php">Categories</a><a href="suppliers.php">Suppliers</a><a href="users.php">Users</a><a href="reports.php">Reports & Expenses</a></nav><?php if($message):?><div class="form-success"><?=e($message)?></div><?php endif;?>
<section class="form-wrap" style="margin:20px 0;max-width:700px"><h2>Adjust stock</h2><p class="muted">Customer checkout automatically decreases stock. Marking a supplier purchase order as Delivered automatically increases stock.</p><form method="post"><div class="field"><label>Product</label><select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> (current: <?=$p['stock']?>)</option><?php endforeach;?></select></div><div class="field"><label>Quantity change (+ add, - remove)</label><input type="number" name="quantity" required></div><div class="field"><label>Reason</label><input name="reason" required value="Stock count adjustment"></div><button class="btn btn-blue">UPDATE STOCK</button></form></section>
<h2>Current stock</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Available stock</th><th>Status</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category_name']??'—')?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><?=$p['stock']<=5?'LOW STOCK':'In stock'?></td></tr><?php endforeach;?></tbody></table></div><h2>Inventory history</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Product</th><th>Change</th><th>Reason</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=e($l['created_at'])?></td><td><?=e($l['product_name']??'Deleted product')?></td><td><?=$l['change_qty']>0?'+':''?><?=$l['change_qty']?></td><td><?=e($l['reason'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/../includes/footer.php';?>